INSERT INTO Filme VALUES(1,1,'Pulp Fiction: Tempo de Violência',1994,154,'Quentin Tarantino','Crime, Drama','As vidas de dois assassinos, um boxeador e a esposa de um gângster se cruzam em uma série de contos violentos e cômicos.','/images/pulp-fiction-poster.jpg','2025-08-12 23:48:40');
INSERT INTO Filme VALUES(2,1,'Polar',2019,118,'Jonas Åkerlund','Ação, Crime','Um assassino prestes a se aposentar se torna o alvo de um grupo de matadores mais jovens e impiedosos, enviados por seu antigo chefe.','/images/polar-poster.jpg','2025-08-12 23:48:40');
INSERT INTO Filme VALUES(3,1,'Meninas Malvadas',2004,97,'Mark Waters','Comédia','Uma adolescente criada na África volta aos EUA e precisa navegar pela hierarquia social tóxica de seu novo colégio, liderado por um grupo de garotas populares.','/images/meninas-malvadas-poster.jpg','2025-08-12 23:48:40');
INSERT INTO Filme VALUES(4,1,'KPop Demon Hunters',2025,112,'Maggie Kang','Fantasia','Quando não estão lotando estádios, as estrelas do K-pop Rumi, Mira e Zoey usam seus poderes secretos para proteger os fãs de ameaças sobrenaturais.','https://a.ltrbxd.com/resized/film-poster/7/2/0/9/5/3/720953-kpop-demon-hunters-0-1000-0-1500-crop.jpg','2025-08-13 04:44:47');
INSERT INTO Filme VALUES(5,1,'Anora',2024,220,'Sean Baker','Drama',unistr('A young sex worker from Brooklyn gets her chance at a Cinderella story when she meets and impulsively marries the son of an oligarch. Once the news reaches Russia, her fairytale is threatened as his parents set out to get the marriage annulled.\u000a\u000a'),'https://a.ltrbxd.com/resized/film-poster/9/5/9/5/4/0/959540-anora-0-1000-0-1500-crop.jpg','2025-08-13 04:47:28');
INSERT INTO Filme VALUES(6,1,'Wicked',2024,260,'Jon M. Chu','Musical',unistr('Na Terra de Oz, uma jovem chamada Elphaba forma uma improvável amizade com uma estudante popular chamada Glinda. Após um encontro com o Mágico de Oz, o relacionamento delas logo chega a uma encruzilhada.\u000a'),'https://a.ltrbxd.com/resized/film-poster/3/3/7/0/3/6/337036-wicked-2024-0-1000-0-1500-crop.jpg','2025-08-13 04:49:55');
INSERT INTO Filme VALUES(7,1,'Wicked: For Good',2025,230,'Jon M. Chu','Musical',unistr('Demonizada como a Bruxa Má do Oeste, Elphaba vive no exílio, enquanto Glinda reside na Cidade Esmeralda. Quando uma multidão furiosa se levanta contra a Bruxa Má, ela precisa se unir com Glinda para transformar a si mesma e todo o Oz, para o bem.\u000a'),'https://a.ltrbxd.com/resized/film-poster/8/7/1/1/4/8/871148-wicked-for-good-0-1000-0-1500-crop.jpg','2025-08-13 17:15:45');
INSERT INTO Filme VALUES(8,1,'A Substância',2024,217,'Coralie Fargeat','Drama',unistr('Elisabeth Sparkle, renomada por um programa de aeróbica, enfrenta um golpe devastador quando seu chefe a demite. Em meio ao seu desespero, um laboratório lhe oferece uma substância que promete transformá-la em uma versão aprimorada.\u000a'),'https://a.ltrbxd.com/resized/film-poster/8/3/8/1/4/0/838140-the-substance-0-1000-0-1500-crop.jpg','2025-08-13 17:18:38');
INSERT INTO Filme VALUES(9,1,'Traga Ela De Volta',2025,104,'Danni Philippou, Michael Philippou','Terror',unistr('"Traga Ela de Volta" (Bring Her Back) é um filme de terror psicológico sobrenatural, dirigido por Danny e Michael Philippou, que acompanha dois meio-irmãos, Andy e Piper, que após a morte do pai, são adotados por Laura. A nova lar, uma casa isolada, esconde segredos e rituais ocultos que ameaçam a relação dos irmãos e a sanidade de todos. \u000a'),'https://a.ltrbxd.com/resized/film-poster/1/0/3/7/6/2/7/1037627-bring-her-back-0-1000-0-1500-crop.jpg','2025-08-13 17:21:38');
INSERT INTO Filme VALUES(10,1,'Quarteto Fantástico: Primeiros Passos',2025,115,'Matt Shakman','Ação, Ficção Cientifica','Um grupo de astronautas passa por uma tempestade cósmica durante seu voo experimental. Ao retornar à Terra, os tripulantes descobrem que possuem novas e bizarras habilidades. Reed Richards pode esticar seu corpo. Sua noiva, Susan Storm, ganha a habilidade de se tornar invisível. Seu irmão mais novo, Johnny Storm, adquiriu o poder de controlar o fogo e voar. Já o piloto Ben Grimm foi transformado em um monstro rochoso. Ao tentar compreender seus poderes, eles têm que lidar com novas ameaças.','https://a.ltrbxd.com/resized/film-poster/5/4/3/9/6/7/543967-the-fantastic-four-first-steps-0-1000-0-1500-crop.jpg','2025-08-13 17:23:17');
